static void print_matrix(int cols, int rows) {
    static char matrix[MAX_COLS][MAX_ROWS];
    static char *katakana = "アァカサタナハマヤャラワガザダバパイィキシチニヒミリヰギジヂビピウゥクスツヌフムユュルグズブヅプエェケセテネヘメレヱゲゼデベペオォコソトノホモヨョロヲゴゾドボポヴッン";
