    for (i = 0; i < rows; i++) {
        for (j = 0; j < cols; j++) {
            if (shadow) {
                matrix[i][j] = ' ';
            } else {
                int char_idx = (j + i * cols + rand() % 100) % (strlen(katakana) + strlen(symbols));
                if (char_idx < strlen(katakana)) {
                    matrix[i][j] = katakana[char_idx];
                } else {
                    matrix[i][j] = symbols[char_idx - strlen(katakana)];
